int blosc_compcode_to_compname(int compcode, const char** compname) { /* <=== blosc_compcode_to_compname */ 
  int code = -1;    /* -1 means non-existent compressor code */
  const char* name = NULL;

  /* Map the compressor code */
  if (compcode == BLOSC_BLOSCLZ)
    name = BLOSC_BLOSCLZ_COMPNAME;
  else if (compcode == BLOSC_LZ4)
    name = BLOSC_LZ4_COMPNAME;
  else if (compcode == BLOSC_LZ4HC)
    name = BLOSC_LZ4HC_COMPNAME;
  else if (compcode == BLOSC_LIZARD)
    name = BLOSC_LIZARD_COMPNAME;
  else if (compcode == BLOSC_SNAPPY)
    name = BLOSC_SNAPPY_COMPNAME;
  else if (compcode == BLOSC_ZLIB)
    name = BLOSC_ZLIB_COMPNAME;
  else if (compcode == BLOSC_ZSTD)
    name = BLOSC_ZSTD_COMPNAME;

  *compname = name;

  /* Guess if there is support for this code */
  if (compcode == BLOSC_BLOSCLZ)
    code = BLOSC_BLOSCLZ;
#if defined(HAVE_LZ4)
  else if (compcode == BLOSC_LZ4)
    code = BLOSC_LZ4;
  else if (compcode == BLOSC_LZ4HC)
    code = BLOSC_LZ4HC;
#endif /* HAVE_LZ4 */
#if defined(HAVE_LIZARD)
  else if (compcode == BLOSC_LIZARD)
    code = BLOSC_LIZARD;
#endif /* HAVE_LIZARD */
#if defined(HAVE_SNAPPY)
  else if (compcode == BLOSC_SNAPPY)
    code = BLOSC_SNAPPY;
#endif /* HAVE_SNAPPY */
#if defined(HAVE_ZLIB)
  else if (compcode == BLOSC_ZLIB)
    code = BLOSC_ZLIB;
#endif /* HAVE_ZLIB */
#if defined(HAVE_ZSTD)
  else if (compcode == BLOSC_ZSTD)
    code = BLOSC_ZSTD;
#endif /* HAVE_ZSTD */

  return code;
}

static /* <=== init_shuffle_implementation */ 
#if defined(_MSC_VER)
__forceinline
#else
inline
#endif
void init_shuffle_implementation(void) {
  /* Initialization could (in rare cases) take place concurrently on
     multiple threads, but it shouldn't matter because the
     initialization should return the same result on each thread (so
     the implementation will be the same). Since that's the case we
     can avoid complicated synchronization here and get a small
     performance benefit because we don't need to perform a volatile
     load on the initialization variable each time this function is
     called. */
#if defined(__GNUC__) || defined(__clang__)
  if (__builtin_expect(!implementation_initialized, 0)) {
#else
    if (!implementation_initialized) {
#endif
    /* Initialize the implementation. */
    host_implementation = get_shuffle_implementation();

    /* Set the flag indicating the implementation has been initialized. */
    implementation_initialized = 1;
  }
}

static uint8_t *get_match(uint8_t *ip, const uint8_t *ip_bound, const uint8_t *ref) { /* <=== get_match */ 
#if !defined(BLOSC_STRICT_ALIGN)
  while (ip < (ip_bound - sizeof(int64_t))) {
    if (*(int64_t*)ref != *(int64_t*)ip) {
      /* Return the byte that starts to differ */
      while (*ref++ == *ip++) {}
      return ip;
    }
    else {
      ip += sizeof(int64_t);
      ref += sizeof(int64_t);
    }
  }
#endif
  /* Look into the remainder */
  while ((ip < ip_bound) && (*ref++ == *ip++)) {}
  return ip;
}

#define HASH_FUNCTION(v, s, h) {      \ /* <=== blosc/blosclz.c:56:58:HASH_FUNCTION:3 */ 
  v = (s * 2654435761U) >> (32U - h); \
}

static uint8_t *get_run(uint8_t *ip, const uint8_t *ip_bound, const uint8_t *ref) { /* <=== get_run */ 
  uint8_t x = ip[-1];
  int64_t value, value2;
  /* Broadcast the value for every byte in a 64-bit register */
  memset(&value, x, 8);
  /* safe because the outer check against ip limit */
  while (ip < (ip_bound - sizeof(int64_t))) {
#if defined(BLOSC_STRICT_ALIGN)
    memcpy(&value2, ref, 8);
#else
    value2 = ((int64_t*)ref)[0];
#endif
    if (value != value2) {
      /* Return the byte that starts to differ */
      while (*ref++ == x) ip++;
      return ip;
    }
    else {
      ip += 8;
      ref += 8;
    }
  }
  /* Look into the remainder */
  while ((ip < ip_bound) && (*ref++ == x)) ip++;
  return ip;
}

void truncate_precision32(uint8_t prec_bits, int32_t nelems, /* <=== truncate_precision32 */ 
                          const int32_t* src, int32_t* dest) {
  if (prec_bits > BITS_MANTISSA_FLOAT) {
    fprintf(stderr, "The precision cannot be larger than %d bits for floats",
            BITS_MANTISSA_FLOAT);
  }
  assert (prec_bits <= BITS_MANTISSA_FLOAT);
  int zeroed_bits = BITS_MANTISSA_FLOAT - prec_bits;
  int32_t mask = ~((1 << zeroed_bits) - 1);
  for (int i = 0; i < nelems; i++) {
    dest[i] = src[i] & mask;
  }
}

uint8_t* pipeline_c(struct thread_context* thread_context, const int32_t bsize, /* <=== pipeline_c */ 
                    const uint8_t* src, const int32_t offset,
                    uint8_t* dest, uint8_t* tmp, uint8_t* tmp2) {
  blosc2_context* context = thread_context->parent_context;
  uint8_t* _src = (uint8_t*)src + offset;
  uint8_t* _tmp = tmp;
  uint8_t* _dest = dest;
  int32_t typesize = context->typesize;
  uint8_t* filters = context->filters;
  uint8_t* filters_meta = context->filters_meta;
  bool memcpyed = context->header_flags & (uint8_t)BLOSC_MEMCPYED;

  /* Prefilter function */
  if (context->prefilter != NULL) {
    // Create new prefilter parameters for this block (must be private for each thread)
    blosc2_prefilter_params pparams;
    memcpy(&pparams, context->pparams, sizeof(pparams));
    pparams.out = _dest;
    pparams.out_size = (size_t)bsize;
    pparams.out_typesize = typesize;
    pparams.out_offset = offset;
    pparams.tid = thread_context->tid;
    pparams.ttmp = thread_context->tmp;
    pparams.ttmp_nbytes = thread_context->tmp_nbytes;
    pparams.ctx = context;

    if (context->prefilter(&pparams) != 0) {
      fprintf(stderr, "Execution of prefilter function failed\n");
      return NULL;
    }

    if (memcpyed) {
      // No more filters are required
      return _dest;
    }
    // Cycle buffers
    _src = _dest;
    _dest = _tmp;
    _tmp = _src;
  }

  /* Process the filter pipeline */
  for (int i = 0; i < BLOSC2_MAX_FILTERS; i++) {
    switch (filters[i]) {
      case BLOSC_SHUFFLE:
        for (int j = 0; j <= filters_meta[i]; j++) {
          shuffle(typesize, bsize, _src, _dest);
          // Cycle filters when required
          if (j < filters_meta[i]) {
            _src = _dest;
            _dest = _tmp;
            _tmp = _src;
          }
        }
        break;
      case BLOSC_BITSHUFFLE:
        bitshuffle(typesize, bsize, _src, _dest, tmp2);
        break;
      case BLOSC_DELTA:
        delta_encoder(src, offset, bsize, typesize, _src, _dest);
        break;
      case BLOSC_TRUNC_PREC:
        truncate_precision(filters_meta[i], typesize, bsize, _src, _dest);
        break;
      default:
        if (filters[i] != BLOSC_NOFILTER) {
          fprintf(stderr, "Filter %d not handled during compression\n", filters[i]);
          return NULL;
        }
    }
    // Cycle buffers when required
    if (filters[i] != BLOSC_NOFILTER) {
      _src = _dest;
      _dest = _tmp;
      _tmp = _src;
    }
  }
  return _src;
}

int blosclz_compress(const int clevel, const void* input, int length, /* <=== blosclz_compress */ 
                     void* output, int maxout) {
  uint8_t* ibase = (uint8_t*)input;
  uint8_t* ip = ibase;
  uint8_t* ip_bound = ibase + length - 1;
  uint8_t* ip_limit = ibase + length - 12;
  uint8_t* op = (uint8_t*)output;
  uint8_t* op_limit;
  uint32_t htab[1U << (uint8_t)HASH_LOG];
  uint32_t hval;
  uint32_t seq;
  uint8_t copy;

  op_limit = op + maxout;

  // Minimum lengths for encoding
  unsigned minlen_[10] = {0, 12, 12, 11, 10, 9, 8, 7, 6, 5};

  // Minimum compression ratios for initiate encoding
  double cratio_[10] = {0, 2, 2, 2, 2, 1.8, 1.6, 1.4, 1.2, 1.1};

  uint8_t hashlog_[10] = {0, HASH_LOG - 2, HASH_LOG - 1, HASH_LOG, HASH_LOG,
                          HASH_LOG, HASH_LOG, HASH_LOG, HASH_LOG, HASH_LOG};
  uint8_t hashlog = hashlog_[clevel];
  // Initialize the hash table to distances of 0
  for (unsigned i = 0; i < (1U << hashlog); i++) {
    htab[i] = 0;
  }

  /* input and output buffer cannot be less than 16 and 66 bytes or we can get into trouble */
  if (length < 16 || maxout < 66) {
    return 0;
  }

  /* When we go back in a match (shift), we obtain quite different compression properties.
   * It looks like 4 is more useful in combination with bitshuffle and small typesizes
   * (compress better and faster in e.g. `b2bench blosclz bitshuffle single 6 6291456 1 19`).
   * Fallback to 4 because it provides more consistent results on small itemsizes.
   *
   * In this block we also check cratios for the beginning of the buffers and
   * eventually discard those that are small (take too long to decompress).
   * This process is called _entropy probing_.
   */
  int ipshift = 4;
  int maxlen;  // maximum length for entropy probing
  int csize_3b;
  int csize_4b;
  double cratio = 0;
  switch (clevel) {
    case 1:
    case 2:
    case 3:
      maxlen = length / 8;
      csize_4b = get_csize(ibase, maxlen, false);
      cratio = (double)maxlen / csize_4b;
      break;
    case 4:
    case 5:
    case 6:
    case 7:
    case 8:
      maxlen = length / 8;
      csize_4b = get_csize(ibase, maxlen, false);
      cratio = (double)maxlen / csize_4b;
      break;
    case 9:
      // case 9 is special.  we need to asses the optimal shift
      maxlen = length / 8;
      csize_3b = get_csize(ibase, maxlen, true);
      csize_4b = get_csize(ibase, maxlen, false);
      ipshift = (csize_3b < csize_4b) ? 3 : 4;
      cratio = (csize_3b < csize_4b) ? ((double)maxlen / csize_3b) : ((double)maxlen / csize_4b);
      break;
    default:
      break;
  }
  // discard probes with small compression ratios (too expensive)
  if (cratio < cratio_ [clevel]) {
    goto out;
  }

  /* we start with literal copy */
  copy = 4;
  *op++ = MAX_COPY - 1;
  *op++ = *ip++;
  *op++ = *ip++;
  *op++ = *ip++;
  *op++ = *ip++;

  /* main loop */
  while (BLOSCLZ_LIKELY(ip < ip_limit)) {
    const uint8_t* ref;
    unsigned distance;
    uint8_t* anchor = ip;    /* comparison starting-point */

    /* find potential match */
    seq = BLOSCLZ_READU32(ip);
    HASH_FUNCTION(hval, seq, hashlog)
    ref = ibase + htab[hval];

    /* calculate distance to the match */
    distance = anchor - ref;

    /* update hash table */
    htab[hval] = (uint32_t) (anchor - ibase);

    if (distance == 0 || (distance >= MAX_FARDISTANCE)) {
      LITERAL(ip, op, op_limit, anchor, copy)
      continue;
    }

    /* is this a match? check the first 4 bytes */
    if (BLOSCLZ_UNLIKELY(BLOSCLZ_READU32(ref) == BLOSCLZ_READU32(ip))) {
      ref += 4;
    } else {
      /* no luck, copy as a literal */
      LITERAL(ip, op, op_limit, anchor, copy)
      continue;
    }

    /* last matched byte */
    ip = anchor + 4;

    /* distance is biased */
    distance--;

    /* get runs or matches; zero distance means a run */
    ip = get_run_or_match(ip, ip_bound, ref, !distance);

    /* length is biased, '1' means a match of 3 bytes */
    ip -= ipshift;

    unsigned len = (int)(ip - anchor);
    // If match is close, let's reduce the minimum length to encode it
    unsigned minlen = (clevel == 9) ? ipshift : minlen_[clevel];

    // Encoding short lengths is expensive during decompression
    // Encode only for reasonable lengths (extensive experiments done)
    if (len < minlen || (len <= 5 && distance >= MAX_DISTANCE)) {
      LITERAL(ip, op, op_limit, anchor, copy)
      continue;
    }

    /* if we have copied something, adjust the copy count */
    if (copy)
      /* copy is biased, '0' means 1 byte copy */
      *(op - copy - 1) = (uint8_t)(copy - 1);
    else
      /* back, to overwrite the copy count */
      op--;
    /* reset literal counter */
    copy = 0;

    /* encode the match */
    if (distance < MAX_DISTANCE) {
      if (len < 7) {
        MATCH_SHORT(op, op_limit, len, distance)
      } else {
        MATCH_LONG(op, op_limit, len, distance)
      }
    } else {
      /* far away, but not yet in the another galaxy... */
      distance -= MAX_DISTANCE;
      if (len < 7) {
        MATCH_SHORT_FAR(op, op_limit, len, distance)
      } else {
        MATCH_LONG_FAR(op, op_limit, len, distance)
      }
    }

    /* update the hash at match boundary */
    seq = BLOSCLZ_READU32(ip);
    HASH_FUNCTION(hval, seq, hashlog)
    htab[hval] = (uint32_t) (ip++ - ibase);
    seq >>= 8U;
    HASH_FUNCTION(hval, seq, hashlog)
    htab[hval] = (uint32_t) (ip++ - ibase);
    /* assuming literal copy */

    if (BLOSCLZ_UNLIKELY(op + 1 > op_limit))
      goto out;
    *op++ = MAX_COPY - 1;
  }

  /* left-over as literal copy */
  while (BLOSCLZ_UNLIKELY(ip <= ip_bound)) {
    if (BLOSCLZ_UNLIKELY(op + 2 > op_limit)) goto out;
    *op++ = *ip++;
    copy++;
    if (BLOSCLZ_UNLIKELY(copy == MAX_COPY)) {
      copy = 0;
      *op++ = MAX_COPY - 1;
    }
  }

  /* if we have copied something, adjust the copy length */
  if (copy)
    *(op - copy - 1) = (uint8_t)(copy - 1);
  else
    op--;

  /* marker for blosclz */
  *(uint8_t*)output |= (1U << 5U);

  return (int)(op - (uint8_t*)output);

  out:
  return 0;
}

static int get_csize(uint8_t* ibase, int maxlen, bool force_3b_shift) { /* <=== get_csize */ 
  uint8_t* ip = ibase;
  int32_t oc = 0;
  uint8_t* ip_bound = ibase + maxlen - 1;
  uint8_t* ip_limit = ibase + maxlen - 12;
  uint32_t htab[1U << (uint8_t)HASH_LOG];
  uint32_t hval;
  uint32_t seq;
  uint8_t copy;

  // Initialize the hash table to distances of 0
  for (unsigned i = 0; i < (1U << HASH_LOG); i++) {
    htab[i] = 0;
  }

  /* we start with literal copy */
  copy = 4;
  oc += 5;

  /* main loop */
  while (BLOSCLZ_LIKELY(ip < ip_limit)) {
    const uint8_t* ref;
    unsigned distance;
    uint8_t* anchor = ip;    /* comparison starting-point */

    /* find potential match */
    seq = BLOSCLZ_READU32(ip);
    HASH_FUNCTION(hval, seq, HASH_LOG)
    ref = ibase + htab[hval];

    /* calculate distance to the match */
    distance = anchor - ref;

    /* update hash table */
    htab[hval] = (uint32_t) (anchor - ibase);

    if (distance == 0 || (distance >= MAX_FARDISTANCE)) {
      LITERAL2(ip, oc, anchor, copy)
      continue;
    }

    /* is this a match? check the first 4 bytes */
    if (BLOSCLZ_UNLIKELY(BLOSCLZ_READU32(ref) == BLOSCLZ_READU32(ip))) {
      ref += 4;
    }
    else {
      /* no luck, copy as a literal */
      LITERAL2(ip, oc, anchor, copy)
      continue;
    }

    /* last matched byte */
    ip = anchor + 4;

    /* distance is biased */
    distance--;

    /* get runs or matches; zero distance means a run */
    ip = get_run_or_match(ip, ip_bound, ref, !distance);

    ip -= force_3b_shift ? 3 : 4;
    unsigned len = (int)(ip - anchor);
    // If match is close, let's reduce the minimum length to encode it
    unsigned minlen = (distance < MAX_DISTANCE) ? 3 : 4;
    // Encoding short lengths is expensive during decompression
    if (len < minlen) {
      LITERAL2(ip, oc, anchor, copy)
      continue;
    }

    /* if we have'nt copied anything, adjust the output counter */
    if (!copy)
      oc--;
    /* reset literal counter */
    copy = 0;

    /* encode the match */
    if (distance < MAX_DISTANCE) {
      if (len >= 7) {
        oc += ((len - 7) / 255) + 1;
      }
      oc += 2;
    }
    else {
      /* far away, but not yet in the another galaxy... */
      if (len >= 7) {
        oc += ((len - 7) / 255) + 1;
      }
      oc += 4;
    }

    /* update the hash at match boundary */
    seq = BLOSCLZ_READU32(ip);
    HASH_FUNCTION(hval, seq, HASH_LOG)
    htab[hval] = (uint32_t) (ip++ - ibase);
    seq >>= 8U;
    HASH_FUNCTION(hval, seq, HASH_LOG)
    htab[hval] = (uint32_t) (ip++ - ibase);
    /* assuming literal copy */
    oc++;

  }

  /* if we have copied something, adjust the copy length */
  if (!copy)
    oc--;

  return (int)oc;
}

int last_filter(const uint8_t* filters, char cmode) { /* <=== last_filter */ 
  int last_index = -1;
  for (int i = BLOSC2_MAX_FILTERS - 1; i >= 0; i--) {
    if (!do_nothing(filters[i], cmode))  {
      last_index = i;
    }
  }
  return last_index;
}

void delta_encoder(const uint8_t* dref, int32_t offset, int32_t nbytes, int32_t typesize, /* <=== delta_encoder */ 
                   const uint8_t* src, uint8_t* dest) {
  int32_t i;
  if (offset == 0) {
    /* This is the reference block, use delta coding in elements */
    switch (typesize) {
      case 1:
        dest[0] = dref[0];
        for (i = 1; i < nbytes; i++) {
          dest[i] = src[i] ^ dref[i-1];
        }
        break;
      case 2:
        ((uint16_t *)dest)[0] = ((uint16_t *)dref)[0];
        for (i = 1; i < nbytes / 2; i++) {
          ((uint16_t *)dest)[i] =
                  ((uint16_t *)src)[i] ^ ((uint16_t *)dref)[i-1];
        }
        break;
      case 4:
        ((uint32_t *)dest)[0] = ((uint32_t *)dref)[0];
        for (i = 1; i < nbytes / 4; i++) {
          ((uint32_t *)dest)[i] =
                  ((uint32_t *)src)[i] ^ ((uint32_t *)dref)[i-1];
        }
        break;
      case 8:
        ((uint64_t *)dest)[0] = ((uint64_t *)dref)[0];
        for (i = 1; i < nbytes / 8; i++) {
          ((uint64_t *)dest)[i] =
                  ((uint64_t *)src)[i] ^ ((uint64_t *)dref)[i-1];
        }
        break;
      default:
        if ((typesize % 8) == 0) {
          delta_encoder(dref, offset, nbytes, 8, src, dest);
        } else {
          delta_encoder(dref, offset, nbytes, 1, src, dest);
        }
    }
  } else {
    /* Use delta coding wrt reference block */
    switch (typesize) {
      case 1:
        for (i = 0; i < nbytes; i++) {
          dest[i] = src[i] ^ dref[i];
        }
        break;
      case 2:
        for (i = 0; i < nbytes / 2; i++) {
          ((uint16_t *) dest)[i] =
                  ((uint16_t *) src)[i] ^ ((uint16_t *) dref)[i];
        }
        break;
      case 4:
        for (i = 0; i < nbytes / 4; i++) {
          ((uint32_t *) dest)[i] =
                  ((uint32_t *) src)[i] ^ ((uint32_t *) dref)[i];
        }
        break;
      case 8:
        for (i = 0; i < nbytes / 8; i++) {
          ((uint64_t *) dest)[i] =
                  ((uint64_t *) src)[i] ^ ((uint64_t *) dref)[i];
        }
        break;
      default:
        if ((typesize % 8) == 0) {
          delta_encoder(dref, offset, nbytes, 8, src, dest);
        } else {
          delta_encoder(dref, offset, nbytes, 1, src, dest);
        }
    }
  }
}

static bool get_run(const uint8_t* ip, const uint8_t* ip_bound) { /* <=== get_run */ 
  uint8_t x = *ip;
  int64_t value, value2;
  /* Broadcast the value for every byte in a 64-bit register */
  memset(&value, x, 8);
  while (ip < (ip_bound - 8)) {
#if defined(BLOSC_STRICT_ALIGN)
    memcpy(&value2, ref, 8);
#else
    value2 = *(int64_t*)ip;
#endif
    if (value != value2) {
      // Values differ.  We don't have a run.
      return false;
    }
    else {
      ip += 8;
    }
  }
  /* Look into the remainder */
  while ((ip < ip_bound) && (*ip == x)) ip++;
  return ip == ip_bound ? true : false;
}

void truncate_precision64(uint8_t prec_bits, int32_t nelems, /* <=== truncate_precision64 */ 
                          const int64_t* src, int64_t* dest) {
  if (prec_bits > BITS_MANTISSA_DOUBLE) {
    fprintf(stderr, "The precision cannot be larger than %d bits for doubles",
            BITS_MANTISSA_DOUBLE);
  }
  assert (prec_bits <= BITS_MANTISSA_DOUBLE);
  int zeroed_bits = BITS_MANTISSA_DOUBLE - prec_bits;
  uint64_t mask = ~((1ULL << zeroed_bits) - 1ULL);
  for (int i = 0; i < nelems; i++) {
    dest[i] = src[i] & mask;
  }
}

void truncate_precision(uint8_t prec_bits, int32_t typesize, int32_t nbytes, /* <=== truncate_precision */ 
                        const uint8_t* src, uint8_t* dest) {
  // Make sure that we don't remove all the bits in mantissa so that we
  // don't mess with NaNs or Infinite representation in IEEE 754:
  // https://en.wikipedia.org/wiki/NaN
  if (prec_bits <= 0) {
    fprintf(stderr, "The precision needs to be at least 1 bit");
  }
  assert (prec_bits > 0);
  switch (typesize) {
    case 4:
      truncate_precision32(prec_bits, nbytes / typesize,
                           (int32_t *)src, (int32_t *)dest);
      break;
    case 8:
      truncate_precision64(prec_bits, nbytes / typesize,
                           (int64_t *)src, (int64_t *)dest);
      break;
    default:
      fprintf(stderr, "Error in trunc-prec filter: Precision for typesize %d "
              "not handled", (int)typesize);
      assert(0);
  }
}

int32_t /* <=== bitshuffle */ 
bitshuffle(const int32_t bytesoftype, const int32_t blocksize,
           const uint8_t *_src, const uint8_t *_dest,
           const uint8_t *_tmp) {
  /* Initialize the shuffle implementation if necessary. */
  init_shuffle_implementation();
  size_t size = blocksize / bytesoftype;
  /* bitshuffle only supports a number of elements that is a multiple of 8. */
  size -= size % 8;
  int ret = (int) (host_implementation.bitshuffle)((void *) _src, (void *) _dest,
                                             size, bytesoftype, (void *) _tmp);
  if (ret < 0) {
    // Some error in bitshuffle (should not happen)
    fprintf(stderr, "the impossible happened: the bitshuffle filter failed!");
    return ret;
  }

  // Copy the leftovers
